wr('chapter20-source-check-02.json',{'range':'9–13','source':'https://fr.wikisource.org/w/index.php?title=Essais/Livre_I/Chapitre_21&oldid=1875612','decisions':[{'slots':[10],'decision':'French volontiers means usually, not voluntary. Clear assertion restored instead of Cotton uncertain double negative. Sexual ability distinct from moral misbehaviour. Danish fully recast preserving anecdotes.'},{'slots':[11],'decision':'Suture is cranial anatomy not seam; clarified both. Venus/solar pun preserved; caudle rendered warm night drink not invented nathjælpedrik.'},{'slots':[12,13],'decision':'Literal constructions rewritten; sacrifices not Christian sacraments; retain author gender attitudes, do not present as editorial advice.'}]})
